import{_ as d,o as t,c as o,a2 as c}from"./chunks/framework.C66fElYV.js";const u=JSON.parse('{"title":"Java Aifei → Go Aifei-Go 移植对照报告","description":"","frontmatter":{},"headers":[],"relativePath":"arch/java-go-comparison.md","filePath":"arch/java-go-comparison.md","lastUpdated":1787494284000}'),a={name:"arch/java-go-comparison.md"};function r(i,e,n,l,s,h){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="java-aifei-→-go-aifei-go-移植对照报告" tabindex="-1">Java Aifei → Go Aifei-Go 移植对照报告 <a class="header-anchor" href="#java-aifei-→-go-aifei-go-移植对照报告" aria-label="Permalink to &quot;Java Aifei → Go Aifei-Go 移植对照报告&quot;">​</a></h1><blockquote><p><strong>核对日期</strong>：2026-07-16 <strong>对照基准</strong>：Java 版 <code>/Users/airhead/WorkSpace/aifei/aifei</code> vs Go 版 <code>/Users/airhead/WorkSpace/aifei/aifei-go</code><strong>范围</strong>：aifei（core）、db、enjoy 三个模块 <strong>方法</strong>：逐方法签名核对，附文件路径与行号。所有结论均基于实际源码阅读，非臆测。</p></blockquote><hr><h2 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to &quot;总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>Java 规模</th><th>Go 规模</th><th>完成度</th><th>主要问题性质</th></tr></thead><tbody><tr><td><strong>aifei core</strong></td><td>58 文件</td><td>8 文件</td><td>~90–95%</td><td>基本无缺失，范式转换合理</td></tr><tr><td><strong>db</strong></td><td>~90 文件</td><td>~27 文件</td><td>~85%</td><td>有 <strong>1 个严重功能性 bug</strong> + 方言/SQL 文件缺口</td></tr><tr><td><strong>enjoy</strong></td><td>~120 文件</td><td>16 文件</td><td>~65%（最低）</td><td>多处 <strong>语义 bug</strong>（不是没写，是写错了）</td></tr></tbody></table><p><strong>核心判断</strong>：enjoy 与 db 各存在若干「已实现但行为错误」的真 bug，应优先于「缺功能」处理。</p><hr><h2 id="一、aifei-core" tabindex="-1">一、aifei core <a class="header-anchor" href="#一、aifei-core" aria-label="Permalink to &quot;一、aifei core&quot;">​</a></h2><p>核心契约（<code>Input</code>/<code>Output</code>/<code>Handler</code>/<code>Interceptor</code>/<code>Plugin</code>/<code>Config</code>）主干齐全，多处做了贴合 Go 的增强。<strong>无阻塞性缺失。</strong></p><h3 id="_1-1-真正缺失-值得补齐" tabindex="-1">1.1 真正缺失（值得补齐） <a class="header-anchor" href="#_1-1-真正缺失-值得补齐" aria-label="Permalink to &quot;1.1 真正缺失（值得补齐）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>优先级</th><th>缺失功能</th><th>Java 现状</th><th>Go 现状</th><th>是否补齐</th></tr></thead><tbody><tr><td>中</td><td><strong>路由表内省 API</strong></td><td><code>Router.getActionMapping()</code> 返回 <code>actionPath → Action</code> 全量映射，用于权限 key、文档生成、调试</td><td><code>aifei/router.go</code> 仅 <code>Lookup(method, path)</code>，<strong>无枚举全部路由的 API</strong>（<code>Walk</code>/<code>Routes</code>/<code>List</code>）</td><td>是。建议加 <code>Walk(visit func(method, path string, handlers []HandlerFunc))</code></td></tr><tr><td>中</td><td><strong>Input 时间访问器</strong></td><td><code>Input.getDate/getLocalDate/getLocalTime/getLocalDateTime</code>，按字符串长度自动推断格式</td><td><code>input.go:22-49</code> 与 <code>http/context.go</code> <strong>无任何时间类型访问器</strong>，只能 <code>GetStr</code> 后自行 <code>time.Parse</code></td><td>较值得。可加 <code>GetTime(key string, layout ...string) time.Time</code></td></tr><tr><td>中低</td><td>路由创建回调</td><td><code>Router.setOnActionCreated(Consumer&lt;Action&gt;)</code>，注册即回调（自动注册权限表、MCP 工具）</td><td><code>Router.Handle</code> 无回调钩子</td><td>可选</td></tr><tr><td>低</td><td>Input 集合类型绑定</td><td><code>getList(name, elementType)</code> / <code>getArray(name, componentType)</code></td><td>无 <code>GetList</code>/<code>GetArray</code>；但 <code>GetBean(&amp;[]T{})</code> 已覆盖大部分场景</td><td>不太必要</td></tr><tr><td>低</td><td>类型化路径参数</td><td><code>getStr(int)</code>/<code>getInt(int)</code> 等按下标取类型化 path 参数</td><td>path 参数只能 <code>PathPara(index)</code> 取 string；且 <code>GetStr/GetInt</code> 只读 query/form 不读 path</td><td>低</td></tr><tr><td>低</td><td>BigDecimal/Enum</td><td><code>getBigDecimal(name)</code>；枚举经 <code>EnumArgument</code> 自动 <code>valueOf</code></td><td>无 <code>GetDecimal</code>（Go 无原生 decimal）</td><td>低</td></tr></tbody></table><h3 id="_1-2-有意省略-语言-范式差异-非缺陷" tabindex="-1">1.2 有意省略（语言/范式差异，非缺陷） <a class="header-anchor" href="#_1-2-有意省略-语言-范式差异-非缺陷" aria-label="Permalink to &quot;1.2 有意省略（语言/范式差异，非缺陷）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Java 功能</th><th>Go 处理方式</th><th>说明</th></tr></thead><tbody><tr><td>IoC 容器（<code>@Inject</code>/<code>@Singleton</code>/<code>Aop</code>/<code>AopFactory</code>/<code>AopKit</code>）</td><td>无 IoC</td><td>Go 无类似机制，合理省略</td></tr><tr><td>CGLIB/Javassist 代理（<code>proxy/</code> 全包、<code>PrototypeInterceptor</code>）</td><td><code>Handler</code> wrapper 链 + <code>Interceptor</code> 接口</td><td>范式转换，等价覆盖</td></tr><tr><td><code>@Before</code>/<code>@Clear</code>/<code>@Path</code>/<code>@Para</code>/<code>@NoPath</code> 注解 + <code>scanner/</code> classpath 扫描</td><td>代码注册 + <code>server.Register</code> 结构反射</td><td>Go 无注解/无 classpath 扫描</td></tr><tr><td><code>argument/</code> 反射式参数注入</td><td>handler 直接收 <code>Input</code></td><td>Go 不做方法参数反射注入</td></tr><tr><td><code>AifeiConfig</code> + <code>Routes</code>/<code>Plugins</code>/<code>Settings</code> 抽象</td><td>函数式选项（<code>WithHandlers</code>/<code>WithPlugin</code>/<code>WithOnStart</code>/<code>WithOnStop</code>）</td><td>有意重新表达</td></tr><tr><td><code>server/Dispatcher</code>/<code>Server</code></td><td><code>./http</code> + <code>./server</code> 模块</td><td>有意拆分</td></tr><tr><td><code>util/Prop</code>/<code>PropKit</code></td><td>独立 <code>config</code> 模块</td><td>通用配置工具，非 core 职责</td></tr><tr><td><code>log/</code> 全包</td><td>独立 <code>log</code> 模块</td><td>有意拆分</td></tr><tr><td><code>util/AppHome</code>/<code>PathUtil</code>/<code>StrUtil</code>/<code>ComputeCache</code></td><td>Go 标准库 + <code>sync.Map</code></td><td>Java 部署/通用工具特有</td></tr></tbody></table><blockquote><p>Java 路由是 flat HashMap、<strong>无 HTTP method 维度</strong>、仅支持尾部单段 pathPara；Go 用 radix 树 + 每 method 一棵 + <code>:param</code>/<code>*catchAll</code>，<strong>反而更丰富</strong>。</p></blockquote><h3 id="_1-3-go-反而超出-java-的地方" tabindex="-1">1.3 Go 反而超出 Java 的地方 <a class="header-anchor" href="#_1-3-go-反而超出-java-的地方" aria-label="Permalink to &quot;1.3 Go 反而超出 Java 的地方&quot;">​</a></h3><ul><li><strong><code>Output</code> 接口</strong>：Java <code>core/Output.java</code> 是空标记接口；Go 有 <code>Code()/Msg()/Data()</code> 结构化实现（<code>output.go</code>）。</li><li><strong>路由路径模式</strong>：支持任意位置具名参数与 catchAll，按 HTTP method 分树。</li><li><strong><code>Input</code> 的 <code>Meta</code></strong>：额外纳入 <code>Context()/Header()/Path()/Body()</code>（transport-agnostic 元数据），分层更清晰。</li></ul><hr><h2 id="二、db" tabindex="-1">二、db <a class="header-anchor" href="#二、db" aria-label="Permalink to &quot;二、db&quot;">​</a></h2><p>核心 API（Db 门面、Dao 链式、Row Active Record、Page 分页、SqlKit Enjoy SQL、6 类 Hook、TypeConverter 主干、dialect SQL 构建）移植<strong>忠实且对等</strong>：18 个操作符、5 个指令、Condition 生成逻辑全部一一对应。</p><h3 id="_2-1-真-bug-必须修" tabindex="-1">2.1 真 Bug（必须修） <a class="header-anchor" href="#_2-1-真-bug-必须修" aria-label="Permalink to &quot;2.1 真 Bug（必须修）&quot;">​</a></h3><h4 id="🔴-bug-1-事务连接不传播-最严重-功能性缺陷" tabindex="-1">🔴 Bug 1：事务连接不传播（最严重，功能性缺陷） <a class="header-anchor" href="#🔴-bug-1-事务连接不传播-最严重-功能性缺陷" aria-label="Permalink to &quot;🔴 Bug 1：事务连接不传播（最严重，功能性缺陷）&quot;">​</a></h4><ul><li><strong>Java</strong>：<code>TransactionKit</code> 用 <code>ThreadLocal</code> 把事务 <code>Connection</code> 绑定到当前线程；事务内所有 <code>Db.sql()</code>/<code>Dao</code> 调用自动复用该连接。</li><li><strong>Go 现状</strong>：<code>TransactionWithID</code>（<code>db/transaction.go</code>）只做 <code>pool.Begin()</code> → <code>fn()</code> → <code>Commit/Rollback</code>，但 <code>fn</code> <strong>拿不到 <code>*sql.Tx</code></strong>；且所有 executor（如 <code>db/executor.go:36</code> <code>config.Pool().Exec</code>）一律直接走 <code>config.Pool()</code> 取新连接并自动提交。</li><li><strong>后果</strong>：<code>db.Transaction(func(){ db.Insert(...); db.Delete(...) })</code> 里的 Insert/Delete <strong>各自独立提交、不在同一事务</strong>。透明事务形同虚设。</li><li><strong>修复方向</strong>：引入 context 传播机制，让 executor 在事务上下文内使用 <code>*sql.Tx</code>。</li></ul><h4 id="🟡-bug-2-row-keep-未同步清理-change-集合" tabindex="-1">🟡 Bug 2：<code>Row.Keep()</code> 未同步清理 change 集合 <a class="header-anchor" href="#🟡-bug-2-row-keep-未同步清理-change-集合" aria-label="Permalink to &quot;🟡 Bug 2：`Row.Keep()` 未同步清理 change 集合&quot;">​</a></h4><ul><li><strong>Java</strong>：<code>keep(fields)</code> 同时过滤 <code>data</code> 和 <code>change</code>。</li><li><strong>Go 现状</strong>：<code>db/row.go:155</code> 的 <code>Keep</code> 只删 <code>r.data</code>，<strong>不动 <code>r.change</code></strong>（对比同文件 <code>Remove</code>/<code>RemoveNullFields</code> 都正确清理两者）。</li><li><strong>后果</strong>：<code>Set(&quot;a&quot;,1).Set(&quot;b&quot;,2).Keep(&quot;a&quot;)</code> 后，<code>change</code> 仍含 <code>&quot;b&quot;</code>，后续 <code>Update()</code> 会用已不存在的字段生成 SQL。</li><li><strong>修复</strong>：一行修改，补上对 <code>r.change</code> 的清理。</li></ul><h3 id="_2-2-真正缺失-高优先级" tabindex="-1">2.2 真正缺失（高优先级） <a class="header-anchor" href="#_2-2-真正缺失-高优先级" aria-label="Permalink to &quot;2.2 真正缺失（高优先级）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>缺失功能</th><th>Java 现状</th><th>Go 现状</th><th>说明</th></tr></thead><tbody><tr><td><strong>4 种数据库方言</strong></td><td>8 种 dialect</td><td><code>db/dialect.go</code> 仅 MySQL/PostgreSQL/SQLite（<code>NewDialect</code> 识别 <code>mysql</code>/<code>postgres</code>/<code>pgx</code>/<code>sqlite</code>/<code>sqlite3</code>）</td><td>缺 Oracle/SqlServer/H2/Informix（含各自分页窗口函数、Oracle <code>.nextval</code>）。详见 2.4</td></tr><tr><td><strong>原生连接逃逸口 <code>call(JdbcFun)</code>/FunExecutor</strong></td><td><code>Dao.call(JdbcFun)</code> 暴露裸 <code>Connection</code>，附 <code>JdbcKit</code>（Enjoy-SQL 解析 + ResultSet→Row）</td><td>无等价物；<code>TxBegin()</code> 仅返回 <code>*sql.Tx</code>，Dao 无 <code>Call</code>/<code>WithConn</code> 钩子</td><td>存储过程、同连接多语句、临时表优化无法实现</td></tr><tr><td><strong>外部 SQL 模板文件加载 + 热重载</strong></td><td><code>SqlKit.addSqlFile(file)</code>、<code>setBaseSqlFilePath</code>、<code>setSqlFileHotReloading(true)</code></td><td>✅ ISSUE-0014 已补齐：<code>AddSqlFile</code>/<code>AddSqlDir</code>(批量)/<code>SetBaseSqlFilePath</code>/<code>SetSqlFileHotReloading</code>/<code>ParseSqlFile</code>（文件内按 <code>#sql</code> 指令分段）+ devMode 热重载</td><td>批量加载 <code>.sql</code> 文件已支持</td></tr></tbody></table><h3 id="_2-3-真正缺失-中-低优先级" tabindex="-1">2.3 真正缺失（中/低优先级） <a class="header-anchor" href="#_2-3-真正缺失-中-低优先级" aria-label="Permalink to &quot;2.3 真正缺失（中/低优先级）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>优先级</th><th>缺失功能</th><th>说明</th></tr></thead><tbody><tr><td>中</td><td>Batch 能力较薄</td><td>缺 <code>batchSize</code>/<code>commitOnBatchSize</code>（分块提交）、<code>getGeneratedKeys</code>（批量回填自增主键）、<code>UpdateCounts</code>、异构批分组 <code>BatchGroup</code>（多表/混列批）。<code>db/batch.go</code> 假定同构，读 <code>rows[0]</code> 取字段</td></tr><tr><td>中</td><td>TypeConverter 缺 BigDecimal 等</td><td>Java 15 个方法；Go 仅 6 个（<code>ToInt/ToInt64/ToFloat64/ToBool/ToString/ToTime</code>）。缺 <code>toBigDecimal</code>（金融痛点）、<code>toBigInteger</code>/<code>toNumber</code>/<code>toShort</code>/<code>toByte</code>/<code>toFloat</code></td></tr><tr><td>中</td><td>事务表达式力降级</td><td>Java <code>transaction(Atom&lt;R&gt;)</code> 返回泛型业务结果，可成功路径主动回滚；Go <code>Transaction(fn func() error) error</code> 只返回 error，<code>server.TxInterceptor</code> 硬编码 <code>Code()!=0</code> 回滚</td></tr><tr><td>中</td><td>复合主键仅 2 列</td><td>Java <code>findByCompositeId(table, String[], Object[])</code> 任意列数；Go 固定 2 列版</td></tr><tr><td>低</td><td><code>Kv</code> 有序 fluent 参数 Map</td><td>用裸 <code>map[string]interface{}</code> 替代，人体工学差</td></tr><tr><td>低</td><td>自定义错误消息回调</td><td><code>findOne(Function&lt;Integer,String&gt;)</code> 无 Go 版</td></tr><tr><td>低</td><td><code>queryField(defaultValue)</code></td><td>无默认值重载</td></tr><tr><td>低</td><td>Row 小缺口</td><td><code>setOrPut</code>、<code>data()</code> 批量读写、<code>get(field, converter)</code> 函数式转换器、schema 感知钩子</td></tr><tr><td>低</td><td>SqlKit 小缺口</td><td><code>#orderBy</code> 未 trim 字段/方向、错误类型静默跳过、<code>ParaDirective.setCheckParaAssigned</code> 全局开关、operator 全小写别名未注册</td></tr><tr><td>低</td><td>ext 简化</td><td><code>SqlLog</code>/<code>SqlFormatter</code> 仅压缩空白，无格式化打印</td></tr></tbody></table><h3 id="_2-4-方言缺口" tabindex="-1">2.4 方言缺口 <a class="header-anchor" href="#_2-4-方言缺口" aria-label="Permalink to &quot;2.4 方言缺口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Java 方言</th><th>Go 等价</th><th>状态</th></tr></thead><tbody><tr><td><code>MysqlDialect</code></td><td><code>MySQLDialect</code></td><td>✅</td></tr><tr><td><code>PostgreSqlDialect</code></td><td><code>PostgresDialect</code></td><td>✅</td></tr><tr><td><code>SqliteDialect</code></td><td><code>SQLiteDialect</code></td><td>✅</td></tr><tr><td><code>OracleDialect</code></td><td>—</td><td>❌ 缺（<code>rownum</code> 三层子查询分页、<code>.nextval</code>、<code>getGeneratedKeys</code>）</td></tr><tr><td><code>SqlServerDialect</code></td><td>—</td><td>❌ 缺（<code>ROW_NUMBER() OVER</code>/<code>OFFSET FETCH</code>、<code>[ ]</code> 引号）</td></tr><tr><td><code>H2Dialect</code></td><td>—</td><td>❌ 缺（Oracle 风格 <code>rownum</code>）</td></tr><tr><td><code>InformixDialect</code></td><td>—</td><td>❌ 缺（<code>SKIP N FIRST M</code>、空格填充引号）</td></tr></tbody></table><h3 id="_2-5-有意省略-非缺口" tabindex="-1">2.5 有意省略（非缺口） <a class="header-anchor" href="#_2-5-有意省略-非缺口" aria-label="Permalink to &quot;2.5 有意省略（非缺口）&quot;">​</a></h3><ul><li><strong>连接池</strong>：<code>DruidSupplier</code>/<code>HikariCpSupplier</code> → Go 用 <code>database/sql</code> 自带连接池（零外部依赖原则）。</li><li><strong>7 个 Factory SPI</strong>（<code>DaoFactory</code>/<code>BatchFactory</code>/<code>RowFactory</code>/<code>ChangeSetFactory</code>/<code>DataMapFactory</code>/<code>HashDataMapFactory</code>/<code>IdSqlFactory</code>）→ Go 用 <code>DbHookKit</code> 钩子作为扩展点。</li><li><strong><code>Murmur3Util</code></strong> → 仅支撑 <code>IdSqlFactory</code> 缓存键，Go 改用显式 <code>sqlID</code>。</li><li><strong><code>PageSqlUtil</code></strong> → 被子查询 count 方案替代（<code>SELECT COUNT(*) FROM (...) AS _cnt</code>，更稳健，无需 <code>removeOrderBy</code> 正则剥离）。</li><li><strong>类型差异</strong>：<code>BigDecimal/BigInteger/Number/Short/Byte</code> 在 Go 无直接对应；<code>Date/LocalDateTime/...</code> 合并为 <code>time.Time</code>。</li><li><strong>旧 JFinal Model API</strong>（<code>_setRowMap</code>/<code>toRecord</code>/<code>copy</code>/<code>reload</code>/<code>refresh</code>/<code>save</code>/<code>Model.java</code>）在当前 Java 版本不存在，非移植缺口。</li></ul><h3 id="_2-6-go-增量-java-无" tabindex="-1">2.6 Go 增量（Java 无） <a class="header-anchor" href="#_2-6-go-增量-java-无" aria-label="Permalink to &quot;2.6 Go 增量（Java 无）&quot;">​</a></h3><ul><li><code>ForInsertOrUpdate</code> upsert（<code>ON DUPLICATE KEY UPDATE</code>/<code>ON CONFLICT DO UPDATE</code>/<code>INSERT OR REPLACE</code>）。</li><li><code>Table</code>/<code>Tables</code>/<code>AutoTables</code> 多表元数据映射（<code>db/table.go</code>）。</li><li><code>KeyFormat</code> JSON 驼峰/蛇形切换。</li><li><code>Row</code> 一等 JSON 编解码（<code>db/json_codec.go</code>）+ <code>DecodeJSONFields</code> 类型化 JSON 列解码。</li><li>顶层 <code>AddSql</code> 门面。</li></ul><hr><h2 id="三、enjoy" tabindex="-1">三、enjoy <a class="header-anchor" href="#三、enjoy" aria-label="Permalink to &quot;三、enjoy&quot;">​</a></h2><p>搭起了 enjoy 的<strong>骨架</strong>：DKFF 双层 lexer/parser、近乎全部指令名、表达式优先级阶梯、基本类型字面量。但「能解析」≠「语义正确」，核心执行语义存在多处偏差与缺口。</p><blockquote><p>覆盖度：指令名解析 ~100%、表达式算子 ~95%；语法覆盖 ~90%，<strong>语义正确度 ~60–65%</strong>。 作为 <strong>SQL 模板引擎</strong>够用；作为<strong>通用 HTML 模板引擎</strong>尚有约 35% 缺口。</p></blockquote><h3 id="_3-1-真-bug-语义错误-高优先级" tabindex="-1">3.1 真 Bug（语义错误，高优先级） <a class="header-anchor" href="#_3-1-真-bug-语义错误-高优先级" aria-label="Permalink to &quot;3.1 真 Bug（语义错误，高优先级）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>位置</th><th>Java 语义</th><th>Go 当前行为</th><th>后果</th></tr></thead><tbody><tr><td>1</td><td><code>enjoy/expr_eval.go:40-65</code></td><td><code>+</code> 任一为 String 时拼接；数值保留 int/long/double 类型</td><td>一律 <code>toFloat64</code> 两侧</td><td><code>&quot;a&quot;+&quot;b&quot;</code>→<code>0</code>；<code>1+2</code>→<code>3.0</code>；<code>10/3</code>→<code>3.333</code>（不拼字符串、不整除）</td></tr><tr><td>2</td><td><code>enjoy/stat_parser.go:371-372</code></td><td><code>ReturnIf</code> 表达式是<strong>条件</strong>，为真才 return</td><td>与 <code>TokReturn</code> 同走 <code>parseReturnStat</code>，expr 当<strong>返回值</strong>且<strong>无条件</strong> return</td><td><code>#returnIf(x&gt;0)</code> 恒返回</td></tr><tr><td>3</td><td><code>enjoy/stat_parser.go:91-108</code> + <code>toSlice</code>(<code>expr_eval.go:512-525</code>)</td><td><code>ForIteratorStatus</code> 支持 Collection/Map(Entry)/数组/Iterator/Iterable/Enumeration/单对象</td><td><code>toSlice</code> 只接受 Slice/Array kind，map 被当单元素</td><td><code>#for x : map</code> 完全失效</td></tr><tr><td>4</td><td><code>enjoy/scope.go:18-26</code></td><td><code>Scope.Get</code> 找不到时回退 <code>sharedObjectMap</code></td><td><code>Get</code> 只查 <code>data</code>/<code>parent</code>，不回退</td><td><code>sharedObjectMap</code> 是<strong>死代码</strong>，<code>AddSharedObject</code>（<code>template.go:126</code>）声称支持但无效</td></tr></tbody></table><h3 id="_3-2-真正缺失-中优先级" tabindex="-1">3.2 真正缺失（中优先级） <a class="header-anchor" href="#_3-2-真正缺失-中优先级" aria-label="Permalink to &quot;3.2 真正缺失（中优先级）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>缺失功能</th><th>Java</th><th>Go</th><th>说明</th></tr></thead><tbody><tr><td><code>#for</code> 缺 <code>#else</code></td><td>循环一次未执行时执行 else 体（<code>For.java:90-92</code>）</td><td><code>ForStat</code> 无 else 概念</td><td>—</td></tr><tr><td><code>#for</code> 循环状态变量不完整</td><td><code>for.index/count/first/last/odd/even/size/outer</code> 对象式访问</td><td>只设扁平 <code>index/size/first/last</code>，缺 <code>count/odd/even/outer</code>；且访问范式不兼容（裸变量 vs <code>for.index</code>）</td><td>模板兼容性差</td></tr><tr><td><code>#call</code> 丢失外围作用域</td><td><code>Define</code> 用 <code>new Scope(scope)</code>（caller 子域，可见外层变量）</td><td><code>CallStat</code> 用 <code>NewScope(empty)</code>（无 parent）</td><td><code>#define</code> 函数体内看不到外层变量</td></tr><tr><td><code>#define</code> 不支持前向引用</td><td>parse 阶段注册（<code>Parser.java:100-103</code>）</td><td>执行时才 <code>env.AddFunction</code>（<code>stat_parser.go:159-161</code>）</td><td>文档顺序靠后的 define 无法被前面的 call 调用</td></tr><tr><td>赋值不支持 <code>ID[expr]=expr</code></td><td><code>map[key]=v</code>/<code>list[i]=v</code>/<code>array[i]=v</code>，可无限连</td><td><code>expr_parser.go:45-49</code> 强制左侧为 <code>IDExpr</code></td><td>仅支持 <code>ID = expr</code></td></tr><tr><td><code>Scope.Set</code> 不向上查找</td><td>set 自内向外找已存在变量就地改写，找不到存根</td><td><code>scope.go:29-34</code> 只写当前层</td><td><code>#for</code> 内 <code>#set(x=...)</code> 外层变量丢失</td></tr><tr><td>内置指令全部缺失</td><td>默认注册 7 个</td><td>0 个</td><td>详见 3.3</td></tr><tr><td>共享方法库</td><td><code>SharedMethodKit</code> + 默认 <code>SharedMethodLib</code>（<code>isEmpty</code>/<code>notEmpty</code>），可注册</td><td>无注册体系</td><td>模板内不能直接 <code>isEmpty(x)</code></td></tr><tr><td>扩展方法缺数值类</td><td>9 类 × ~9 方法（<code>toBoolean/toInt/.../toBigDecimal</code>）</td><td>仅 <code>expr_eval.go:377-427</code> 硬编码 string 方法</td><td>无数值扩展，无注册机制</td></tr><tr><td><code>EngineConfig</code> 配置项大面积缺失</td><td>compressor/outputDirectiveFactory/sourceFactory/sharedMethodKit/keepLineBlankDirectives/roundingMode/staticMethod/Field/addSharedFunction(file)</td><td>仅 directiveMap/sharedFunctionMap/sharedObjectMap/baseTemplatePath/encoding/datePattern/devMode（后三项基本未接线）</td><td>—</td></tr><tr><td>Field 取值不支持 getter 约定</td><td>优先 <code>getXxx()</code> getter → public field → Model/Record/Map.get()</td><td><code>getField</code>(<code>expr_eval.go:327-351</code>) 只 <code>reflect.FieldByName</code> + Map index</td><td>只暴露 getter 的 POJO 不友好</td></tr></tbody></table><h3 id="_3-3-缺失的内置指令-扩展方法-共享方法" tabindex="-1">3.3 缺失的内置指令 / 扩展方法 / 共享方法 <a class="header-anchor" href="#_3-3-缺失的内置指令-扩展方法-共享方法" aria-label="Permalink to &quot;3.3 缺失的内置指令 / 扩展方法 / 共享方法&quot;">​</a></h3><p><strong>内置指令（Java 默认 7 个，Go 0 个）：</strong></p><table tabindex="0"><thead><tr><th>Java 指令</th><th>作用</th><th>Go</th></tr></thead><tbody><tr><td><code>#date</code></td><td>日期格式化</td><td>缺</td></tr><tr><td><code>#escape</code></td><td>HTML 转义 <code>&lt; &gt; &quot; &#39; &amp;</code></td><td>缺</td></tr><tr><td><code>#number</code></td><td>数字格式化（DecimalFormat）</td><td>缺</td></tr><tr><td><code>#random</code></td><td>输出随机整数</td><td>缺</td></tr><tr><td><code>#render</code></td><td>动态渲染子模板</td><td>缺</td></tr><tr><td><code>#string(name)</code></td><td>多行字符串变量定义</td><td>缺</td></tr><tr><td><code>#call</code></td><td>动态调用（表达式函数名）</td><td>Go 的 <code>#@</code> 是语法糖，非等价指令</td></tr></tbody></table><blockquote><p>HTML 转义：Java 默认 <code>#(...)</code> 不转义（与 Go 一致），但转义靠 <code>#escape</code> 显式开启；Go 连 <code>#escape</code> 都没有，无法显式转义。</p></blockquote><p><strong>扩展方法</strong>：Java 9 类（Integer/Long/Short/Byte/Float/Double/BigDecimal/BigInteger/String Ext）× ~9 方法；Go 仅硬编码 string 方法（<code>length/trim/upper/contains/startsWith/.../isEmpty</code>），无数值扩展、无注册机制。</p><p><strong>共享方法</strong>：Java 默认 <code>SharedMethodLib</code>（<code>isEmpty</code>/<code>notEmpty</code>）；Go 完全缺失。</p><h3 id="_3-4-低优先级差异" tabindex="-1">3.4 低优先级差异 <a class="header-anchor" href="#_3-4-低优先级差异" aria-label="Permalink to &quot;3.4 低优先级差异&quot;">​</a></h3><blockquote><p>注：以下多项已由 ISSUE-0012 第一轮对齐 Java，标注 ✅；其余为仍存差异或 Go 限制。</p></blockquote><ul><li>✅ <code>??</code> 优先级：Java <code>nullSafe()</code> 位于 mulDivMod(* / %) 与 unary 之间、左结合链式；Go 已对齐（旧为 postfix 高优先级）。</li><li>Map 字面量 key：Java 允许 number/bool/null/ID/STR；Go 只允许 ID/STR。</li><li>✅ <code>#@name?()</code> 安全调用：词法器正确剥离 <code>?</code>→<code>TokCallIfDefined</code>，函数名干净；nullSafe 跳过、非 nullSafe 抛异常（对齐 Java）。</li><li>✅ <code>::</code> 静态访问：模板路径默认禁用对齐 Java（<code>isStaticMethodExpressionEnabled=false</code>）；<strong>Go 限制：无 Class.forName / 结构体静态方法，且无法整体反射 import 包的包级函数</strong>——开启后以 <code>AddStatic(alias, obj)</code> 注册一个 struct 实例作命名空间，反射其所有导出方法，<code>alias::method(args)</code> 即可调用（作 Java 导入工具类静态方法的等价；要导标准库包级函数需用 struct 包一层）。</li><li>✅ <code>#include</code> 相对路径：相对父文件目录解析，无父目录回退 baseTemplatePath（对齐 Java）。</li><li>✅ Call 参数个数：不匹配抛异常（对齐 Java）；nullSafe 仍跳过。</li><li><code>ClassPathSource</code>：Java 有 classpath/file/string；Go 只有 file/string。</li><li>✅ 错误行号定位：解析期 + directive 参数期 + 渲染期 error 均带「文件名:行号」（<code>locateError</code>/<code>renderError</code>，节点持 <code>nodeLoc</code>、<code>StatList.Exec</code> 跟踪 <code>ctrl.curLine</code>，对照 Java <code>Location</code>/<code>ParseException</code>/<code>TemplateException</code>）；<code>errorStat</code> 已在前序 issue 移除。</li></ul><h3 id="_3-5-有意省略-非缺口" tabindex="-1">3.5 有意省略（非缺口） <a class="header-anchor" href="#_3-5-有意省略-非缺口" aria-label="Permalink to &quot;3.5 有意省略（非缺口）&quot;">​</a></h3><ul><li><code>proxy/</code>（ProxyClass/ProxyClassLoader/ProxyCompiler，字节码生成编译器）— Go 无运行时动态子类需求。</li><li><code>io/</code> 性能 writer 体系（FloatingDecimal 1306 行 JDK 浮点格式化移植、FloatingWriter/IntegerWriter/LongWriter/.../Utf8Encoder）— Go 统一用 <code>io.Writer</code> + <code>fmt.Sprintf</code>。</li><li><code>expr/ast</code> 反射缓存基建（FastFieldGetter/FieldGetters/FieldKeyBuilder/MethodKeyBuilder/MethodKit/MethodInfo/...）— Go 直接用 <code>reflect</code>。</li><li><code>stat/Compressor</code>/<code>LineCompressor</code>/<code>CharTable</code> — 模板输出空白压缩优化。</li><li><code>util/</code>（HashUtil/ComputeCache/InstanceUtil/JavaKeyword）— 服务于 Java 反射缓存/实例化。</li></ul><hr><h2 id="四、优先级建议-补齐路线" tabindex="-1">四、优先级建议（补齐路线） <a class="header-anchor" href="#四、优先级建议-补齐路线" aria-label="Permalink to &quot;四、优先级建议（补齐路线）&quot;">​</a></h2><h3 id="第一阶段-修-bug-性价比最高" tabindex="-1">第一阶段：修 Bug（性价比最高） <a class="header-anchor" href="#第一阶段-修-bug-性价比最高" aria-label="Permalink to &quot;第一阶段：修 Bug（性价比最高）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bug</th><th>工作量</th><th>影响</th></tr></thead><tbody><tr><td><code>#returnIf</code> 语义（enjoy）</td><td>局部</td><td>模板控制流错误</td></tr><tr><td><code>Row.Keep()</code> change 清理（db）</td><td>一行</td><td>UPDATE 字段错误</td></tr><tr><td><code>sharedObjectMap</code> 回退（enjoy）</td><td>局部</td><td>死代码激活</td></tr><tr><td>算术 <code>+</code> 字符串拼接 + int 保留（enjoy）</td><td>局部</td><td>基础表达式能力</td></tr><tr><td>Map 迭代（enjoy）</td><td>局部</td><td><code>#for x : map</code></td></tr><tr><td><strong>db 事务连接传播</strong></td><td>中（需 context 贯穿 executor）</td><td><strong>最严重</strong>，事务失效</td></tr></tbody></table><h3 id="第二阶段-enjoy-可用性提升" tabindex="-1">第二阶段：enjoy 可用性提升 <a class="header-anchor" href="#第二阶段-enjoy-可用性提升" aria-label="Permalink to &quot;第二阶段：enjoy 可用性提升&quot;">​</a></h3><p>补 <code>#escape</code>/<code>#date</code>/<code>#number</code> 内置指令 → <code>#for</code> else + 循环状态变量 → <code>#call</code>/<code>#define</code> 作用域与前向引用 → 共享方法库 <code>isEmpty</code>。</p><h3 id="第三阶段-db-工程化" tabindex="-1">第三阶段：db 工程化 <a class="header-anchor" href="#第三阶段-db-工程化" aria-label="Permalink to &quot;第三阶段：db 工程化&quot;">​</a></h3><p><s>去掉 SqlKit 空 stub，实现 <code>.sql</code> 文件加载</s>（✅ ISSUE-0014 已完成）→ 补 Oracle/SqlServer 方言 → Batch 回填主键/异构分组。</p><hr><h2 id="附录-关键文件路径" tabindex="-1">附录：关键文件路径 <a class="header-anchor" href="#附录-关键文件路径" aria-label="Permalink to &quot;附录：关键文件路径&quot;">​</a></h2><h3 id="go-侧" tabindex="-1">Go 侧 <a class="header-anchor" href="#go-侧" aria-label="Permalink to &quot;Go 侧&quot;">​</a></h3><ul><li>aifei core：<code>aifei/{input.go,output.go,aifei.go,router.go,handler.go,interceptor.go,config.go,plugin.go}</code></li><li>Input 实现：<code>http/context.go</code>、<code>server/in.go</code></li><li>db 事务：<code>db/transaction.go</code>、<code>db/executor.go</code></li><li>db <code>Keep</code> bug：<code>db/row.go:155</code></li><li>db 方言：<code>db/dialect.go</code></li><li>db Batch：<code>db/batch.go</code></li><li>db SQL 文件 stub：<code>db/sql/kit.go:144</code></li><li>db TypeConverter：<code>db/type_converter.go</code></li><li>enjoy 语义：<code>enjoy/stat_parser.go</code>、<code>enjoy/expr_parser.go</code>、<code>enjoy/expr_eval.go</code>、<code>enjoy/scope.go</code>、<code>enjoy/engine_config.go</code>、<code>enjoy/lexer.go</code></li></ul><h3 id="java-侧-对照基准" tabindex="-1">Java 侧（对照基准） <a class="header-anchor" href="#java-侧-对照基准" aria-label="Permalink to &quot;Java 侧（对照基准）&quot;">​</a></h3><ul><li>core：<code>aifei/src/main/java/cn/aifei/core/{Input.java,Output.java}</code></li><li>enjoy：<code>aifei-enjoy/src/main/java/cn/aifei/enjoy/stat/Parser.java</code>、<code>stat/ast/{For.java,ReturnIf.java,Define.java}</code>、<code>stat/Scope.java</code>、<code>expr/ExprParser.java</code>、<code>expr/ast/{Arith.java,Assign.java}</code>、<code>EngineConfig.java</code></li><li>db：<code>aifei-db/src/main/java/cn/aifei/db/{core,transaction,dialect,executor,hook,sql}/</code></li></ul>',67)])])}const p=d(a,[["render",r]]);export{u as __pageData,p as default};
